@r1.c3 w.request.constraint request=$r1 on=attribute attribute=drawn.distanceGrade value="just a touch" operator=degree phase=result
@r1.c4 w.request.constraint request=$r1 on=place attribute=drawn.anchor value="the path" operator=relation phase=selector
@r1.c5 w.request.constraint request=$r1 on=size attribute=drawn.size value=long operator=degree phase=result
